import{_ as e,o as t,c as o,a2 as s}from"./chunks/framework.D7Ov6LBE.js";const u=JSON.parse('{"title":"Agendamento Universal — Design Inicial","description":"","frontmatter":{},"headers":[],"relativePath":"projetos/agendamento-universal.md","filePath":"projetos/agendamento-universal.md","lastUpdated":1786499417000}'),n={name:"projetos/agendamento-universal.md"};function d(r,a,i,l,p,c){return t(),o("div",null,[...a[0]||(a[0]=[s(`<h1 id="agendamento-universal-—-design-inicial" tabindex="-1">Agendamento Universal — Design Inicial <a class="header-anchor" href="#agendamento-universal-—-design-inicial" aria-label="Permalink to &quot;Agendamento Universal — Design Inicial&quot;">​</a></h1><blockquote><p><strong>Status: FASE 1 CONCLUÍDA — domínio puro + API + E2E verdes</strong> (2026-08-12) <strong>Norte</strong>: <em>&quot;O melhor e simples sistema de agendamento possível para integrar no ecossistema ERP genérico.&quot;</em><strong>Repo</strong>: <code>bbanho/agendamento-universal</code> (privado, hexagonal TS+Bun) · <strong>ADR</strong>: <a href="./adr-001-agendamento">ADR-001</a></p></blockquote><hr><h2 id="_1-visao-1-pagina" tabindex="-1">1. Visão (1 página) <a class="header-anchor" href="#_1-visao-1-pagina" aria-label="Permalink to &quot;1. Visão (1 página)&quot;">​</a></h2><p>Um sistema de agendamento <strong>completo, simples e genérico</strong> que vive dentro do ecossistema ERP: traduz tipos de dados em <strong>full duplex</strong> com o ERP e sistemas adjacentes, com o <strong>primeiro cliente</strong> sendo clínicas médicas (consultas).</p><p><strong>Princípios:</strong></p><ol><li><strong>Simples primeiro</strong> — qualquer complexidade (pipeline, canônico, LLM) só entra se pagar o próprio custo.</li><li><strong>Integrado, não ilha</strong> — o sistema é um componente do ecossistema; fala com o ERP nos dois sentidos.</li><li><strong>Vertical-agnóstico</strong> — nada de setor no núcleo; setor entra por adaptador.</li><li><strong>Regras em português, LLM como componente</strong> — regras de negócio declaradas em pt-BR, interpretadas por LLM (design-time), fora do domínio puro.</li></ol><h2 id="_2-arquitetura-hexagonal" tabindex="-1">2. Arquitetura (hexagonal) <a class="header-anchor" href="#_2-arquitetura-hexagonal" aria-label="Permalink to &quot;2. Arquitetura (hexagonal)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Decisão</th><th>Escolha</th></tr></thead><tbody><tr><td><strong>Formato</strong></td><td>Hexagonal: domínio puro + portas + adaptadores bijetivos</td></tr><tr><td><strong>Casos de uso</strong></td><td>Steps tipados, cada um testável isoladamente</td></tr><tr><td><strong>Concorrência</strong></td><td>UoW + lock no reserva de slot (dois pacientes, mesmo horário)</td></tr><tr><td><strong>Canônico</strong></td><td>FHIR-inspired simplificado: <code>Patient</code>, <code>Practitioner</code>, <code>Schedule</code>, <code>Slot</code>, <code>Appointment</code></td></tr><tr><td><strong>LLM</strong></td><td>Design-time (regras em pt-BR → configuração determinística); runtime só p/ casos de borda</td></tr></tbody></table><h2 id="_3-diagrama-—-fluxo-minimo-paciente-↔-agenda-↔-erp" tabindex="-1">3. Diagrama — fluxo mínimo (paciente ↔ agenda ↔ ERP) <a class="header-anchor" href="#_3-diagrama-—-fluxo-minimo-paciente-↔-agenda-↔-erp" aria-label="Permalink to &quot;3. Diagrama — fluxo mínimo (paciente ↔ agenda ↔ ERP)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        ┌────────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>        │                        AGENDAMENTO (hexagonal)                     │</span></span>
<span class="line"><span>        │                                                                    │</span></span>
<span class="line"><span>CLÍNICA │   ┌──────────────┐   ┌──────────────────┐   ┌──────────────────┐   │</span></span>
<span class="line"><span>  web   │   │ Casos de uso │──►│     DOMÍNIO      │──►│   Portas saída   │   │</span></span>
<span class="line"><span> ──────►│   │  (entrada)   │   │   (puro, pt-BR)  │   │  (adaptadores)   │   │</span></span>
<span class="line"><span>agendar │   │ Agendar      │   │  slots, buffers  │   │  AgendaPort      │──►│──► Postgres</span></span>
<span class="line"><span>        │   │ Consultar     │   │  prioridade…    │   │  NotificacaoPort │──►│──► WhatsApp/email</span></span>
<span class="line"><span>        │   │ Remarcar      │   └────────┬─────────┘   │  ERPAdapterPort  │──►│──► ERP (full duplex)</span></span>
<span class="line"><span>        │   │ Cancelar      │            │             └──────────────────┘   │</span></span>
<span class="line"><span>        │   └──────────────┘            │                                     │</span></span>
<span class="line"><span>        └────────────────────────────────┼────────────────────────────────────┘</span></span>
<span class="line"><span>                                         │ RegrasPort (LLM, design-time)</span></span>
<span class="line"><span>                                         ▼</span></span>
<span class="line"><span>                              regras/agendamento.pt-BR.md</span></span>
<span class="line"><span>                              (versionadas no repo, golden tests)</span></span></code></pre></div><p><strong>Full duplex com o ERP:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> ERP ──importa──►  catálogo de serviços + pacientes          (escrita na agenda)</span></span>
<span class="line"><span> ERP ◄──exporta──  compromissos criados/alterados/cancelados  (eventos → webhook)</span></span></code></pre></div><h2 id="_4-casos-de-uso-minimos-primeiro-cliente-consultas" tabindex="-1">4. Casos de uso mínimos (primeiro cliente: consultas) <a class="header-anchor" href="#_4-casos-de-uso-minimos-primeiro-cliente-consultas" aria-label="Permalink to &quot;4. Casos de uso mínimos (primeiro cliente: consultas)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Caso de uso</th><th>Entrada</th><th>Saída</th><th>Regra simples (pt-BR)</th></tr></thead><tbody><tr><td>UC-01</td><td><code>ConsultarDisponibilidade</code></td><td>médico, período</td><td>slots livres</td><td><em>&quot;médico não atende em 2 horários seguidos sem pausa de 15 min&quot;</em></td></tr><tr><td>UC-02</td><td><code>AgendarConsulta</code></td><td>paciente, médico, slot</td><td>compromisso reservado</td><td><em>&quot;retorno tem prioridade sobre 1ª consulta&quot;</em></td></tr><tr><td>UC-03</td><td><code>RemarcarConsulta</code></td><td>compromisso, novo slot</td><td>compromisso movido + evento</td><td><em>&quot;remarcação só até 24h antes&quot;</em></td></tr><tr><td>UC-04</td><td><code>CancelarConsulta</code></td><td>compromisso, motivo</td><td>cancelado + evento</td><td><em>&quot;cancelamento libera o slot imediatamente&quot;</em></td></tr><tr><td>UC-05</td><td><code>SincronizarERP</code></td><td>eventos pendentes</td><td>ERP atualizado (idempotente)</td><td><em>&quot;cada evento é enviado uma única vez&quot;</em></td></tr></tbody></table><h2 id="_5-estado-real-—-fase-1-2026-08-12" tabindex="-1">5. Estado real — Fase 1 (2026-08-12) <a class="header-anchor" href="#_5-estado-real-—-fase-1-2026-08-12" aria-label="Permalink to &quot;5. Estado real — Fase 1 (2026-08-12)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Estado</th><th>Evidência</th></tr></thead><tbody><tr><td>Domínio puro (regras R1–R5 em pt-BR)</td><td>✅</td><td>17 testes golden/usecases</td></tr><tr><td>Adapter SQLite real (<code>bun:sqlite</code>, lock otimista atômico)</td><td>✅</td><td>5 testes (corrida D4)</td></tr><tr><td>API HTTP (Bun.serve, seed demo, full duplex ERP mock)</td><td>✅</td><td>E2E 7/7 (API)</td></tr><tr><td>Frontend demo (HTML single-file)</td><td>✅</td><td>E2E browser 8/8 + screenshot</td></tr><tr><td>ADR-001 (hexagonal + TS/Bun + golden tests)</td><td>✅</td><td>publicado nesta wiki</td></tr></tbody></table><p><strong>Comandos</strong>: <code>bun run dev</code> (API :3000 + demo) · <code>bun run test</code> · <code>bun run e2e</code> · <code>bun run typecheck</code></p><h2 id="_6-proximos-passos" tabindex="-1">6. Próximos passos <a class="header-anchor" href="#_6-proximos-passos" aria-label="Permalink to &quot;6. Próximos passos&quot;">​</a></h2><ol><li>✅ Visão + diagrama + UC mínimos (design aceito)</li><li>✅ ADR-001 + repo <code>bbanho/agendamento-universal</code> + kanban</li><li>✅ Fase 1: domínio puro → portas → adaptadores (SQLite) → API → E2E 8/8</li><li>⬜ <strong>Adapter ERP real</strong> (TISS/FHIR) — substitui <code>MemoryErp</code> mantendo o domínio untouched</li><li>⬜ Wiki própria <code>docs.axio.eng.br/agendamento/</code> (multi-projeto no mesmo hub)</li><li>⬜ LLM design-time: regras pt-BR → código (golden tests como contrato)</li></ol><hr><p><em>Pivô: discutir sobre este texto — cada linha é uma decisão.</em></p>`,22)])])}const g=e(n,[["render",d]]);export{u as __pageData,g as default};
